import { Fragment, type ReactNode } from 'react';

/**
 * A small, dependency-free renderer for the Markdown subset the judge's pass
 * report uses (2026-09-08): headings (#..####), paragraphs, bullet and
 * numbered lists (one level), bold, italic, inline code, and a fenced code
 * block. Anything else renders as literal text — nothing is interpreted as
 * HTML, so model output can never inject markup.
 *
 * Deliberately not a full Markdown implementation: the report is generated by
 * our own prompt (judge_llm.synthesize_pass) from a fixed outline, and a
 * ~1 kB renderer is easier to trust than a library for that.
 */

// Underscore emphasis only at word boundaries (CommonMark's intra-word rule):
// instance ids like `django__django-11239` and identifiers like `tool_efficiency`
// are text, not italics — the judge report is full of both (found live 2026-09-08).
const INLINE_RE =
  /(`[^`]+`|\*\*[^*]+\*\*|\*[^*]+\*|(?<![\w_])_(?!_)[^_]+_(?![\w_]))/g;

function renderInline(text: string): ReactNode[] {
  const out: ReactNode[] = [];
  let i = 0;
  for (const part of text.split(INLINE_RE)) {
    if (!part) continue;
    const key = i++;
    if (part.startsWith('`') && part.endsWith('`') && part.length > 2) {
      out.push(
        <code
          key={key}
          className="rounded bg-zinc-100 px-1 font-mono text-[11px] dark:bg-zinc-800"
        >
          {part.slice(1, -1)}
        </code>,
      );
    } else if (
      part.startsWith('**') &&
      part.endsWith('**') &&
      part.length > 4
    ) {
      out.push(<strong key={key}>{part.slice(2, -2)}</strong>);
    } else if (
      (part.startsWith('*') && part.endsWith('*') && part.length > 2) ||
      (part.startsWith('_') && part.endsWith('_') && part.length > 2)
    ) {
      out.push(<em key={key}>{part.slice(1, -1)}</em>);
    } else {
      out.push(<Fragment key={key}>{part}</Fragment>);
    }
  }
  return out;
}

type Block =
  | { kind: 'heading'; level: number; text: string }
  | { kind: 'paragraph'; text: string }
  | { kind: 'list'; ordered: boolean; items: string[] }
  | { kind: 'code'; text: string };

function parseBlocks(source: string): Block[] {
  const lines = source.replace(/\r\n?/g, '\n').split('\n');
  const blocks: Block[] = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim() === '') {
      i++;
      continue;
    }
    if (line.startsWith('```')) {
      const buf: string[] = [];
      i++;
      while (i < lines.length && !lines[i].startsWith('```')) {
        buf.push(lines[i]);
        i++;
      }
      i++; // closing fence (or EOF)
      blocks.push({ kind: 'code', text: buf.join('\n') });
      continue;
    }
    const heading = /^(#{1,4})\s+(.*)$/.exec(line);
    if (heading) {
      blocks.push({
        kind: 'heading',
        level: heading[1].length,
        text: heading[2].trim(),
      });
      i++;
      continue;
    }
    const bullet = /^\s*[-*•]\s+(.*)$/;
    const numbered = /^\s*\d+[.)]\s+(.*)$/;
    if (bullet.test(line) || numbered.test(line)) {
      const ordered = numbered.test(line);
      const re = ordered ? numbered : bullet;
      const items: string[] = [];
      while (i < lines.length) {
        const m = re.exec(lines[i]);
        if (m) {
          items.push(m[1]);
          i++;
        } else if (
          items.length > 0 &&
          /^\s{2,}\S/.test(lines[i]) &&
          !bullet.test(lines[i]) &&
          !numbered.test(lines[i])
        ) {
          // continuation line of the previous item
          items[items.length - 1] += ' ' + lines[i].trim();
          i++;
        } else {
          break;
        }
      }
      blocks.push({ kind: 'list', ordered, items });
      continue;
    }
    // paragraph: consecutive non-blank, non-special lines
    const buf: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() !== '' &&
      !lines[i].startsWith('```') &&
      !/^#{1,4}\s/.test(lines[i]) &&
      !bullet.test(lines[i]) &&
      !numbered.test(lines[i])
    ) {
      buf.push(lines[i].trim());
      i++;
    }
    blocks.push({ kind: 'paragraph', text: buf.join(' ') });
  }
  return blocks;
}

const HEADING_CLASS: Record<number, string> = {
  1: 'mt-3 text-sm font-semibold first:mt-0',
  2: 'mt-3 text-sm font-semibold first:mt-0',
  3: 'mt-2 text-xs font-semibold uppercase tracking-wide text-zinc-500 first:mt-0',
  4: 'mt-2 text-xs font-semibold first:mt-0',
};

export function Markdown({
  source,
  className,
}: {
  source: string;
  className?: string;
}) {
  const blocks = parseBlocks(source);
  return (
    <div className={className} data-testid="markdown">
      {blocks.map((b, idx) => {
        switch (b.kind) {
          case 'heading': {
            const cls = HEADING_CLASS[b.level] ?? HEADING_CLASS[4];
            if (b.level <= 2)
              return (
                <h4 key={idx} className={cls}>
                  {renderInline(b.text)}
                </h4>
              );
            return (
              <h5 key={idx} className={cls}>
                {renderInline(b.text)}
              </h5>
            );
          }
          case 'paragraph':
            return (
              <p key={idx} className="mt-1.5 text-xs leading-relaxed">
                {renderInline(b.text)}
              </p>
            );
          case 'list': {
            const Tag = b.ordered ? 'ol' : 'ul';
            return (
              <Tag
                key={idx}
                className={
                  (b.ordered ? 'list-decimal' : 'list-disc') +
                  ' mt-1.5 space-y-0.5 pl-5 text-xs leading-relaxed'
                }
              >
                {b.items.map((item, j) => (
                  <li key={j}>{renderInline(item)}</li>
                ))}
              </Tag>
            );
          }
          case 'code':
            return (
              <pre
                key={idx}
                className="mt-1.5 overflow-x-auto rounded bg-zinc-100 p-2 font-mono text-[11px] dark:bg-zinc-800"
              >
                {b.text}
              </pre>
            );
        }
      })}
    </div>
  );
}
